Pruebas unitarias (JUnit, Jest-Vitest, p.ejemplo:
func TestDiscount(t *testing.T) {
  cases := []struct{ total, want float64 }{{100, 90}, {50, 50}}
  for _, tc := range cases {
    if got := ApplyDiscount(tc.total); got != tc.want {
      t.Errorf("ApplyDiscount(%v) = %v; want %v", tc.total, got, tc.want)
    }
  }
}

